bool readExportsOrModuleDotExports (uint16_t ch) {
  uint16_t* revertPos = pos;
  if (ch == 'm' && str_eq5(pos + 1, 'o', 'd', 'u', 'l', 'e')) {
    pos += 6;
    ch = commentWhitespace();
    if (ch != '.') {
      pos = revertPos;
      return false;
