    pos++;
    ch = commentWhitespace();
  }
  if (ch == 'e' && str_eq6(pos + 1, 'x', 'p', 'o', 'r', 't', 's')) {
    pos += 7;
    return true;
  }
  else {
    pos = revertPos;
    return false;
  }
}

void tryParseModuleExportsDotAssign () {
  pos += 6;
  uint16_t* revertPos = pos - 1;
  uint16_t ch = commentWhitespace();
  if (ch == '.') {
    pos++;
    ch = commentWhitespace();
    if (ch == 'e' && str_eq6(pos + 1, 'x', 'p', 'o', 'r', 't', 's')) {
      tryParseExportsDotAssign(true);
      return;
    }
  }
  pos = revertPos;
}

void tryParseExportsDotAssign (bool assign) {
  pos += 7;
  uint16_t* revertPos = pos - 1;
  uint16_t ch = commentWhitespace();
  switch (ch) {
    // exports.asdf
    case '.': {
      pos++;
      ch = commentWhitespace();
      uint16_t* startPos = pos;
      if (identifier(ch)) {
        uint16_t* endPos = pos;
        ch = commentWhitespace();
        if (ch == '=') {
          addExport(startPos, endPos);
          return;
        }
      }
      break;
    }
    // exports['asdf']
    case '[': {
      pos++;
      ch = commentWhitespace();
      if (ch == '\'' || ch == '"') {
        uint16_t* startPos = pos;
        stringLiteral(ch);
        uint16_t* endPos = ++pos;
        ch = commentWhitespace();
        if (ch != ']') break;
        pos++;
        ch = commentWhitespace();
        if (ch != '=') break;
        addExport(startPos, endPos);
      }
      break;
    }
    // module.exports =
    case '=': {
      if (assign) {
        clearReexports();
        pos++;
        ch = commentWhitespace();
        // { ... }
        if (ch == '{') {
          tryParseLiteralExports();
          return;
        }

        // require('...')
        if (ch == 'r')
          tryParseRequire(ExportAssign);
      }
    }
  }
  pos = revertPos;
}

bool tryParseRequire (enum RequireType requireType) {
  uint16_t* revertPos = pos;
  // require('...')
  if (str_eq6(pos + 1, 'e', 'q', 'u', 'i', 'r', 'e')) {
    pos += 7;
    uint16_t ch = commentWhitespace();
    if (ch == '(') {
      pos++;
      ch = commentWhitespace();
      uint16_t* reexportStart = pos;
      if (ch == '\'' || ch == '"') {
        stringLiteral(ch);
        uint16_t* reexportEnd = ++pos;
        ch = commentWhitespace();
        if (ch == ')') {
          switch (requireType) {
            case ExportStar:
              addReexport(reexportStart, reexportEnd);
              return true;
            case ExportAssign:
              addReexport(reexportStart, reexportEnd);
              return true;
            default:
              starExportStack->specifier_start = reexportStart;
              starExportStack->specifier_end = reexportEnd;
              return true;
          }
        }
      }
    }
    pos = revertPos;
  }
  return false;
}

void tryParseLiteralExports () {
  uint16_t* revertPos = pos - 1;
  while (pos++ < end) {
    uint16_t ch = commentWhitespace();
    uint16_t* startPos = pos;
    if (identifier(ch)) {
      uint16_t* endPos = pos;
      ch = commentWhitespace();
      if (ch == ':') {
        pos++;
        ch = commentWhitespace();
        // nothing more complex than identifier expressions for now
        if (!identifier(ch)) {
          pos = revertPos;
          return;
        }
        ch = *pos;
      }
      addExport(startPos, endPos);
    }
    else if (ch == '\'' || ch == '"') {
      uint16_t* startPos = pos;
      stringLiteral(ch);
      uint16_t* endPos = ++pos;
      ch = commentWhitespace();
      if (ch == ':') {
        pos++;
        ch = commentWhitespace();
        // nothing more complex than identifier expressions for now
        if (!identifier(ch)) {
          pos = revertPos;
          return;
        }
        ch = *pos;
        addExport(startPos, endPos);
      }
    }
    else if (ch == '.' && str_eq2(pos + 1, '.', '.')) {
      pos += 3;
      if (*pos == 'r' && tryParseRequire(ExportAssign)) {
        pos++;
      }
      else if (!identifier(*pos)) {
        pos = revertPos;
        return;
      }
      ch = commentWhitespace();
    }
    else {
      pos = revertPos;
      return;
    }

    if (ch == '}')
      return;

    if (ch != ',') {
      pos = revertPos;
      return;
    }
  }
