  "categories": [
    {
      "name": "CJS 命名导出检测",
      "description": "识别 exports.name = value、module.exports.name = value、exports['name'] = value、Object.defineProperty(exports, 'name', {value:...}) 等多种导出声明模式",
      "evidence": ["lexer.js:40-53 (parseCJS)", "lexer.js:874-931 (tryParseExportsDotAssign)", "lexer.js:333-457 (tryParseObjectDefineOrKeys)"]
    },
    {
      "name": "CJS 重新导出检测",
      "description": "识别 module.exports = require('...') 及其在对象字面量中的 spread 形式 {...require('...')}，同时检测 Babel/TypeScript/tslib 的转译输出模式（__export/__exportStar、Object.keys + forEach 星导出）",
      "evidence": ["lexer.js:933-965 (tryParseRequire)", "lexer.js:967-1028 (tryParseLiteralExports)", "lexer.js:459-832 (tryParseObjectDefineOrKeys: Object.keys forEach star export)"]
    },
    {
      "name": "WebAssembly 加速解析",
