      "evidence": ["src/lexer.c (C 词法分析器核心)", "src/lexer.js:264-282 (Wasm 加载与 init/initSync)", "lib/lexer.wasm"]
    },
    {
      "name": "转译工具输出识别",
      "description": "内置对 Babel、TypeScript、RollupJS 等工具输出的 CJS 转译模式的精准匹配，包括 var _external = require(...) 与 Object.keys(_external).forEach 等常见模式，确保转译后代码的导出可被正确检测",
      "evidence": ["lexer.js:252-289 (tryBacktrackAddStarExportBinding)", "lexer.js:459-832 (Object.keys forEach 星导出完整匹配)", "README.md:329-362"]
    }
